const mach=eq=>`<g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${MZ[eq==="esp"||eq==="mol"?eq:"aut"]}</g>`;
const tf=s=>Math.floor(s/60)+":"+String(Math.floor(s%60)).padStart(2,"0");
Object.assign(S,{ac:{seg:"all",eq:"all",df:"all",q:""},done:{},pl:null});let PT=0;
